// Width, collapsed, open nodes, hidden sections and recents survive a reload.
const PERSIST = { key: "kitora.sidebar.clickup", storage: localStorageAdapter() }

/** A ClickUp-style workspace: switcher, counts, Favourites and Recents, Spaces → folders → lists, menus, rename, drag, Customise and the user menu. */
export function ClickUpApp() {
  const [nav, setNav] = useState(NAV)
  // In an app, pass the router's pathname as \`location\` and let the links navigate; this demo keeps navigation in the page.
  const [location, setLocation] = useState("/cu/home")
  const navigate = (item: NavItem, event: { preventDefault(): void }) => {
    if (item.external || !item.href) return
    event.preventDefault()
    setLocation(item.href)
  }
  const { title, crumbs } = crumbsFor(nav, location)
  return (
    <div className="relative h-full overflow-hidden" style={{ ...THEME }}>
      <SidebarStyles />
      <SidebarProvider icons={ICONS} location={location} persist={PERSIST} label="ClickUp navigation" toggleShortcut defaultState={{ expanded: ["eng", "backend", "frontend"] }}>
        <SidebarLayout edgeSwipe sidebar={<ClickUpSidebar nav={nav} setNav={setNav} navigate={navigate} />}>
          <ListView title={title} crumbs={crumbs} toolbar={<CollapsedTrigger />} />
        </SidebarLayout>
      </SidebarProvider>
    </div>
  )
}
